#!/usr/bin/env python
# SPDX-License-Identifier: AGPL-3.0-or-later
"""D-68: chrF++ of our models against the Gemini-generated Urhobo silver set (CPU, greedy). Reported ONLY as "agreement with Gemini-Urhobo": the references were generated by Gemini and not checked
by a native speaker, they contain an unknown rate of errors, and the set must never be used for model selection. Set A (60 very short phrases) and sets B-F (170 sentences) are scored separately.

    python scripts/urh_silver_eval.py --silver urhobo_gemini_silver_2026-10-22.jsonl --model final_1433=/workspace/sft_build/runs/final_1433 \
        --model A2W_alpha0.7=/workspace/jobs/r7/models/sci_sft_A2W_alpha0.7 --out urh_silver_eval.json [--hyp-dir DIR]

Each model's hypotheses are written to <hyp-dir>/<name>.jsonl, so a model whose weights are not on the box can be scored from its own predictions: `--preds NAME=file.jsonl` (rows in the order of the silver file, field `hyp`).
Bootstrap: 1,000 resamples of the sentences, percentile 95 % interval of the corpus chrF++ (sacrebleu word_order = 2).
"""
from __future__ import annotations

import argparse
import json
import os
import random
import sys
import time

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))


def chrf(hyps, refs):
    from sacrebleu.metrics import CHRF

    return CHRF(word_order=2).corpus_score(hyps, [refs]).score


def boot(hyps, refs, n=1000, seed=0):
    rng = random.Random(seed)
    idx = list(range(len(hyps)))
    vals = []
    for _ in range(n):
        s = [rng.choice(idx) for _ in idx]
        vals.append(chrf([hyps[i] for i in s], [refs[i] for i in s]))
    vals.sort()
    return vals[int(0.025 * n)], vals[int(0.975 * n)]


def generate(path, rows, batch_size, max_new_tokens, threads):
    import torch

    from gemma_mt.eval import runtime as RT
    from gemma_mt.eval.eval_translation import generate_translations
    from gemma_mt.modeling import load_model

    torch.set_num_threads(threads)
    ref = RT.resolve_model(path)
    tok, stop, pad = RT.load_tokenizer_and_stops(ref.path)
    model = load_model(ref.path, attn_implementation="sdpa", dtype=torch.float32, device="cpu")
    out = generate_translations(model, tok, [dict(english=r["english"], iso="urh", reference=r["urhobo"]) for r in rows], stop_ids=stop.ids, pad_id=pad, device="cpu",
                                batch_size=batch_size, max_new_tokens=max_new_tokens)
    return [o["hyp"] for o in out], [o["finished"] for o in out]


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--silver", required=True)
    ap.add_argument("--model", action="append", default=[], help="NAME=path")
    ap.add_argument("--preds", action="append", default=[], help="NAME=jsonl with `hyp` per silver row")
    ap.add_argument("--out", required=True)
    ap.add_argument("--hyp-dir", default=None)
    ap.add_argument("--batch-size", type=int, default=16)
    ap.add_argument("--max-new-tokens", type=int, default=160)
    ap.add_argument("--threads", type=int, default=8)
    a = ap.parse_args()
    rows = [json.loads(l) for l in open(a.silver, encoding="utf-8")]
    res = {}
    todo = [(s.split("=", 1)[0], "model", s.split("=", 1)[1]) for s in a.model] + [(s.split("=", 1)[0], "preds", s.split("=", 1)[1]) for s in a.preds]
    for name, kind, path in todo:
        t0 = time.time()
        if kind == "model":
            hyps, fin = generate(path, rows, a.batch_size, a.max_new_tokens, a.threads)
        else:
            pr = [json.loads(l) for l in open(path, encoding="utf-8")]
            hyps, fin = [p["hyp"] for p in pr], [True] * len(pr)
        if a.hyp_dir:
            os.makedirs(a.hyp_dir, exist_ok=True)
            with open(os.path.join(a.hyp_dir, name + ".jsonl"), "w", encoding="utf-8") as f:
                for r, h, fi in zip(rows, hyps, fin):
                    f.write(json.dumps({"set": r["set"], "english": r["english"], "silver": r["urhobo"], "hyp": h, "finished": fi}, ensure_ascii=False) + "\n")
        res[name] = {}
        for label, sel in (("A", lambda r: r["set"] == "A"), ("B-F", lambda r: r["set"] != "A")):
            ix = [i for i, r in enumerate(rows) if sel(r)]
            h, rf = [hyps[i] for i in ix], [rows[i]["urhobo"] for i in ix]
            lo, hi = boot(h, rf)
            res[name][label] = {"n": len(ix), "chrf": chrf(h, rf), "ci95": [lo, hi], "finished": sum(fin[i] for i in ix) / len(ix), "empty": sum(1 for x in h if not x.strip()) / len(ix)}
        print(name, {k: (round(v["chrf"], 1), [round(x, 1) for x in v["ci95"]], v["n"]) for k, v in res[name].items()}, f"{time.time() - t0:.0f}s", flush=True)
    json.dump({"note": "agreement with Gemini-Urhobo (silver, not native-verified); never for model selection", "results": res}, open(a.out, "w"), indent=1)


if __name__ == "__main__":
    main()
